import re

CODE_RE = re.compile("^[A-Za-z0-9]{4,32}$")
TARGET = "https://example.com/page?a=1&b=two#frag"


def test_creating_a_link_returns_201_with_a_base62_code_and_the_url_echoed_verbatim(app):
    response = app.create(TARGET)

    assert response.status_code == 201, response.text[:300]
    body = response.json()
    assert CODE_RE.match(body["code"] or ""), "unusable code: " + repr(body.get("code"))
    assert body["url"] == TARGET, "url must be echoed byte for byte, got " + repr(body.get("url"))
    rows = app.link_rows()
    assert len(rows) == 1, rows
    assert rows[0]["code"] == body["code"]
    assert rows[0]["url"] == TARGET


