    code = app.create(TARGET).json()["code"]

    response = app.visit(code)

    assert response.status_code == 307, (
        "the design pins a temporary 307 redirect, got {0}: {1}".format(
            response.status_code, response.text[:200]
        )
    )
    assert response.headers.get("location") == TARGET, (
        "Location must be the stored target unmodified, got "
        + repr(response.headers.get("location"))
    )
    assert "no-store" in response.headers.get("cache-control", "").lower(), (
        "a counted redirect must not be cached, Cache-Control was "
        + repr(response.headers.get("cache-control"))
    )


def test_short_url_is_links_base_url_joined_to_the_code_without_a_double_slash(app_factory):
