    body = app.create("https://example.com/a").json()

    assert body["short_url"] == "https://sho.rt/" + body["code"], body


def test_two_links_each_redirect_to_their_own_target_and_not_to_each_others(app):
    first = app.create("https://example.com/first").json()["code"]
    second = app.create("https://example.com/second").json()["code"]

    assert first != second
    assert app.visit(first).headers["location"] == "https://example.com/first"
    assert app.visit(second).headers["location"] == "https://example.com/second"


def test_the_creation_response_reports_an_expiry_strictly_after_the_creation_time(app, parse_ts):
    body = app.create(TARGET).json()

    created = parse_ts(body["created_at"])
    expires = parse_ts(body["expires_at"])
    assert expires > created, (body["created_at"], body["expires_at"])
