"},{"path":"tests_pipeline/test_link_expiry_behaviour.py","content":""""Expiry, controlled by writing the stored expiry -- never by sleeping."""
from datetime import datetime, timedelta, timezone

import pytest


def _past(seconds=5):
    return datetime.now(timezone.utc) - timedelta(seconds=seconds)


def test_a_link_whose_expiry_has_passed_no_longer_redirects(app, assert_error):
    code = app.create("https://example.com/gone").json()["code"]
    app.set_expiry(code, _past())

    response = app.visit(code)

    assert response.status_code == 410, (
        "an expired link must not redirect; got {0}: {1}".format(
            response.status_code, response.text[:200]
        )
    )
    assert assert_error(response)["code"] == "link_expired"
    assert "location" not in set(k.lower() for k in response.headers.keys()), (
        "an expired link must not still hand out a Location header"
    )


def test_visiting_an_expired_link_records_no_click(app):
    code = app.create("https://example.com/gone").json()["code"]
    app.set_expiry(code, _past(3600))

    for _ in range(3):
        assert app.visit(code).status_code == 410

    assert app.click_rows() == [], "a refused redirect was counted as a click"


def test_a_link_whose_expiry_is_still_ahead_redirects_normally(app):
    code = app.create("https://example.com/live").json()["code"]
    app.set_expiry(code, datetime.now(timezone.utc) + timedelta(hours=1))

    response = app.visit(code)

    assert response.status_code == 307, response.text[:200]
    assert response.headers["location"] == "https://example.com/live"


@pytest.mark.parametrize(
    "value",
    ["2000-01-01T00:00:00Z", "1999-12-31T23:59:59.999999Z"],
    ids=["millennium", "just_before"],
)
def test_creating_a_link_with_an_expiry_in_the_past_is_refused_and_stores_nothing(
    app, assert_error, value
):
    response = app.create("https://example.com/a", expires_at=value)

    assert response.status_code in (400, 422), (value, response.text[:200])
    assert_error(response)
    assert app.link_rows() == []


def test_an_expired_link_still_reports_the_clicks_it_collected_while_live(app):
    code = app.create("https://example.com/gone").json()["code"]
    assert app.visit(code).status_code == 307
    app.set_expiry(code, _past(60))

    assert app.visit(code).status_code == 410
    stats = app.stats(code)

    assert stats.status_code == 200, stats.text[:200]
    body = stats.json()
    assert body["code"] == code
    assert body["total_clicks"] == 1, (
        "the live click must survive expiry and the 410 must not be counted"
    )
"},{"path":"tests_pipeline/test_per_ip_rate_limit.py","content":""""Per-IP creation limiting: 429 past the limit, per key, and window bounded."""
CALLER = "203.0.113.10"
OTHER = "198.51.100.7"


def _limited(app_factory, **extra):
    return app_factory(
        LINKS_RATE_LIMIT_ENABLED="true", LINKS_TRUST_FORWARDED_FOR="true", **extra
    )


def test_the_eleventh_unkeyed_creation_from_one_address_is_refused_with_429(app_factory, assert_error):
    app = _limited(app_factory)

    for i in range(10):
        response = app.create("https://example.com/{0}".format(i), xff=CALLER)
        assert response.status_code == 201, (i, response.status_code, response.text[:200])

    blocked = app.create("https://example.com/eleven", xff=CALLER)

    assert blocked.status_code == 429, (
        "the 11th creation in the window must be refused, got {0}: {1}".format(
            blocked.status_code, blocked.text[:200]
        )
    )
    error = assert_error(blocked)
    assert error["code"] == "rate_limited", error
    retry_after = blocked.headers.get("retry-after")
    assert retry_after is not None, "a 429 must carry Retry-After"
    assert 1 <= int(retry_after) <= 60, retry_after


def test_a_throttled_creation_writes_no_row(app_factory):
    app = _limited(app_factory)
    for i in range(10):
        app.create("https://example.com/{0}".format(i), xff=CALLER)

    assert app.create("https://example.com/eleven", xff=CALLER).status_code == 429

    assert app.count_links() == 10, "the refused request still created a link"


def test_another_client_address_still_succeeds_after_the_first_is_throttled(app_factory):
    app = _limited(app_factory)
    for i in range(10):
        assert app.create("https://example.com/{0}".format(i), xff=CALLER).status_code == 201
    assert app.create("https://example.com/over", xff=CALLER).status_code == 429

    other = app.create("https://example.com/other", xff=OTHER)

    assert other.status_code == 201, (
        "the limit must be per caller, not global: " + other.text[:200]
    )
    assert app.count_links() == 11


def test_links_rate_limit_max_is_read_from_the_environment(app_factory):
    app = _limited(app_factory, LINKS_RATE_LIMIT_MAX="2")

    first = app.create("https://example.com/1", xff=CALLER)
    second = app.create("https://example.com/2", xff=CALLER)
    third = app.create("https://example.com/3", xff=CALLER)

    assert (first.status_code, second.status_code) == (201, 201)
    assert third.status_code == 429, third.text[:200]
    assert app.count_links() == 2


def test_a_throttled_address_may_create_again_once_the_window_has_advanced(app_factory, fake_clock):
    app = _limited(app_factory, LINKS_RATE_LIMIT_MAX="2")
    clock = fake_clock(app)
    assert clock.installed, (
        "the limiter's clock is not substitutable; the design requires "
        "app.state.rate_limiter.clock so windows can be advanced without sleeping"
    )

    assert app.create("https://example.com/1", xff=CALLER).status_code == 201
    assert app.create("https://example.com/2", xff=CALLER).status_code == 201
    assert app.create("https://example.com/3", xff=CALLER).status_code == 429

    clock.advance(61)
    after = app.create("https://example.com/4", xff=CALLER)

    assert after.status_code == 201, (
        "the window is 60s; after 61 simulated seconds the caller must be served "
        "again, got {0}: {1}".format(after.status_code, after.text[:200])
    )
    assert app.count_links() == 3


def test_redirects_and_stats_are_never_refused_by_the_creation_limit(app_factory):
    app = _limited(app_factory, LINKS_RATE_LIMIT_MAX="1")
    code = app.create("https://example.com/a", xff=CALLER).json()["code"]
    assert app.create("https://example.com/b", xff=CALLER).status_code == 429

    for _ in range(5):
        assert app.visit(code, xff=CALLER).status_code == 307
    assert app.stats(code).status_code == 200
    assert app.health().status_code == 200


def test_disabling_the_limiter_removes_every_429(app_factory):
    app = app_factory(LINKS_RATE_LIMIT_ENABLED="false", LINKS_TRUST_FORWARDED_FOR="true")

    for i in range(15):
        response = app.create("https://example.com/{0}".format(i), xff=CALLER)
        assert response.status_code == 201, (i, response.text[:200])

    assert app.count_links() == 15
"},{"path":"tests_pipeline/test_api_key_quota_limits.py","content":""""Per-API-key quotas from SHORTENER_API_KEYS.

Every test drives POST /api/links through the HTTP surface against its own
database and its own freshly started application, so the startup-only key table
is rebuilt each time.
"""
ALPHA_BETA = "alpha:100,beta:20"


def _keyed(app_factory, keys=ALPHA_BETA, **extra):
    return app_factory(
        SHORTENER_API_KEYS=keys, LINKS_RATE_LIMIT_ENABLED="true", **extra
    )


def test_one_hundred_alpha_keyed_creations_succeed_and_the_hundred_and_first_is_429(app_factory):
    app = _keyed(app_factory, LINKS_RATE_LIMIT_MAX="10")

    for i in range(100):
        response = app.create("https://example.com/a{0}".format(i), key="alpha")
        assert response.status_code == 201, (
            "keyed creation {0} of quota 100 was refused with {1}: {2}".format(
                i + 1, response.status_code, response.text[:200]
            )
        )

    over = app.create("https://example.com/over", key="alpha")

    assert over.status_code == 429, (
        "the 101st alpha creation must exceed the quota, got {0}".format(over.status_code)
    )
    assert app.count_links() == 100


def test_a_quota_429_carries_the_rate_limited_envelope_retry_after_and_no_store(app_factory, assert_error):
    app = _keyed(app_factory, keys="alpha:2", LINKS_RATE_LIMIT_MAX="50")
    assert app.create("https://example.com/1", key="alpha").status_code == 201
    assert app.create("https://example.com/2", key="alpha").status_code == 201

    refused = app.create("https://example.com/3", key="alpha")

    assert refused.status_code == 429, refused.text[:200]
    error = assert_error(refused)
    assert error["code"] == "rate_limited", error
    retry_after = refused.headers.get("retry-after")
    assert retry_after is not None, "a quota 429 must carry Retry-After"
    assert 1 <= int(retry_after) <= 60, retry_after
    assert "no-store" in refused.headers.get("cache-control", "").lower(), (
        repr(refused.headers.get("cache-control"))
    )
    assert app.count_links() == 2, "the refused keyed request wrote a row"


def test_beta_gets_its_own_smaller_quota_of_twenty(app_factory):
    app = _keyed(app_factory, LINKS_RATE_LIMIT_MAX="10")

    for i in range(20):
        response = app.create("https://example.com/b{0}".format(i), key="beta")
        assert response.status_code == 201, (i, response.status_code, response.text[:200])

    over = app.create("https://example.com/b-over", key="beta")

    assert over.status_code == 429, (
        "beta's quota is 20, the 21st must be refused, got {0}".format(over.status_code)
    )
    assert app.count_links() == 20


def test_one_exhausted_key_does_not_throttle_a_different_key(app_factory):
    app = _keyed(app_factory, keys="alpha:2,beta:3", LINKS_RATE_LIMIT_MAX="50")
    app.create("https://example.com/1", key="alpha")
    app.create("https://example.com/2", key="alpha")
    assert app.create("https://example.com/3", key="alpha").status_code == 429

    other = app.create("https://example.com/4", key="beta")

    assert other.status_code == 201, (
        "beta has its own counter and must still be served: " + other.text[:200]
    )
    assert app.count_links() == 3


def test_a_known_key_is_bounded_by_its_quota_and_not_also_by_the_per_ip_limit(app_factory):
    app = _keyed(app_factory, LINKS_RATE_LIMIT_MAX="10")

    statuses = [
        app.create("https://example.com/k{0}".format(i), key="alpha").status_code
        for i in range(11)
    ]

    assert statuses == [201] * 11, (
        "a recognised key must use its quota instead of, not in addition to, "
        "LINKS_RATE_LIMIT_MAX: " + repr(statuses)
    )
    assert app.count_links() == 11


def test_a_keys_counter_is_shared_across_client_addresses(app_factory):
    app = _keyed(
        app_factory,
        keys="alpha:3",
        LINKS_RATE_LIMIT_MAX="50",
        LINKS_TRUST_FORWARDED_FOR="true",
    )

    for i in range(3):
        response = app.create(
            "https://example.com/{0}".format(i), key="alpha", xff="203.0.113.10"
        )
        assert response.status_code == 201, (i, response.text[:200])

    from_elsewhere = app.create(
        "https://example.com/4", key="alpha", xff="198.51.100.7"
    )

    assert from_elsewhere.status_code == 429, (
        "one key must not buy extra allowance by moving to another address, got "
        "{0}".format(from_elsewhere.status_code)
    )
    assert app.count_links() == 3


def test_an_unknown_key_shares_the_per_ip_bucket_with_unkeyed_traffic(app_factory):
    app = _keyed(app_factory, LINKS_RATE_LIMIT_MAX="10")

    for i in range(10):
        key = "gamma" if i % 2 else None
        response = app.create("https://example.com/{0}".format(i), key=key)
        assert response.status_code == 201, (i, response.status_code, response.text[:200])

    over = app.create("https://example.com/eleven", key="gamma")

    assert over.status_code == 429, (
        "an unrecognised key must not create a fresh allowance, got {0}".format(
            over.status_code
        )
    )
    assert app.count_links() == 10


def test_key_matching_is_case_sensitive_so_upper_case_alpha_is_unknown(app_factory):
    app = _keyed(app_factory, LINKS_RATE_LIMIT_MAX="10")

    for i in range(10):
        response = app.create("https://example.com/{0}".format(i), key="ALPHA")
        assert response.status_code == 201, (i, response.text[:200])

    over = app.create("https://example.com/eleven", key="ALPHA")

    assert over.status_code == 429, (
        "ALPHA is not alpha and must fall back to the per-IP limit of 10, got "
        "{0}".format(over.status_code)
    )
    assert app.count_links() == 10


def test_an_empty_or_whitespace_key_header_is_treated_as_no_key(app_factory):
    app = _keyed(app_factory, LINKS_RATE_LIMIT_MAX="10")

    for i in range(10):
        key = "" if i % 2 else "   "
        response = app.create("https://example.com/{0}".format(i), key=key)
        assert response.status_code == 201, (i, response.status_code, response.text[:200])

    over = app.create("https://example.com/eleven", key="")

    assert over.status_code == 429, (
        "a blank key must fall back to the per-IP bucket, got {0}".format(
            over.status_code
        )
    )
    assert app.count_links() == 10


def test_with_shortener_api_keys_unset_the_header_changes_nothing(app_factory):
    app = app_factory(
        SHORTENER_API_KEYS=None,
        LINKS_RATE_LIMIT_ENABLED="true",
        LINKS_RATE_LIMIT_MAX="10",
    )

    for i in range(10):
        response = app.create("https://example.com/{0}".format(i), key="alpha")
        assert response.status_code == 201, (i, response.text[:200])

    over = app.create("https://example.com/eleven", key="alpha")

    assert over.status_code == 429, (
        "with no configured keys the header must have no effect, got {0}".format(
            over.status_code
        )
    )
    assert app.count_links() == 10


def test_malformed_key_entries_are_ignored_while_a_valid_entry_still_works(app_factory):
    app = _keyed(
        app_factory,
        keys="alpha,beta:abc,gamma:0,delta:-5,:5,,epsilon:12",
        LINKS_RATE_LIMIT_MAX="3",
    )

    for i in range(12):
        response = app.create("https://example.com/e{0}".format(i), key="epsilon")
        assert response.status_code == 201, (
            "epsilon:12 is the one well formed entry and must be honoured; request "
            "{0} got {1}: {2}".format(i + 1, response.status_code, response.text[:200])
        )
    assert app.create("https://example.com/e-over", key="epsilon").status_code == 429

    for i in range(3):
        response = app.create("https://example.com/b{0}".format(i), key="beta")
        assert response.status_code == 201, (i, response.text[:200])
    fallback = app.create("https://example.com/b-over", key="beta")

    assert fallback.status_code == 429, (
        "beta:abc is malformed, so beta must fall back to LINKS_RATE_LIMIT_MAX=3, "
        "got {0}".format(fallback.status_code)
    )
    assert app.count_links() == 15


def test_whitespace_around_keys_and_quotas_is_stripped(app_factory):
    app = _keyed(app_factory, keys=" alpha : 100 , beta:20 ", LINKS_RATE_LIMIT_MAX="3")

    alpha = [
        app.create("https://example.com/a{0}".format(i), key="alpha").status_code
        for i in range(4)
    ]
    beta = [
        app.create("https://example.com/b{0}".format(i), key="beta").status_code
        for i in range(20)
    ]
    beta_over = app.create("https://example.com/b-over", key="beta")

    assert alpha == [201] * 4, (
        "' alpha ' must be recognised as alpha with quota 100: " + repr(alpha)
    )
    assert beta == [201] * 20, repr(beta)
    assert beta_over.status_code == 429, beta_over.text[:200]
    assert app.count_links() == 24


def test_a_repeated_key_takes_the_quota_of_its_last_occurrence(app_factory):
    app = _keyed(app_factory, keys="alpha:5,alpha:9", LINKS_RATE_LIMIT_MAX="50")

    statuses = [
        app.create("https://example.com/{0}".format(i), key="alpha").status_code
        for i in range(9)
    ]
    tenth = app.create("https://example.com/tenth", key="alpha")

    assert statuses == [201] * 9, (
        "the last occurrence (9) must win over the first (5): " + repr(statuses)
    )
    assert tenth.status_code == 429, tenth.text[:200]
    assert app.count_links() == 9


def test_a_throttled_key_is_served_again_once_the_window_has_advanced(app_factory, fake_clock):
    app = _keyed(app_factory, keys="alpha:2", LINKS_RATE_LIMIT_MAX="50")
    clock = fake_clock(app)
    assert clock.installed, (
        "the limiter's clock is not substitutable; the design requires "
        "app.state.rate_limiter.clock so windows can be advanced without sleeping"
    )

    assert app.create("https://example.com/1", key="alpha").status_code == 201
    assert app.create("https://example.com/2", key="alpha").status_code == 201
    assert app.create("https://example.com/3", key="alpha").status_code == 429

    clock.advance(61)
    after = app.create("https://example.com/4", key="alpha")

    assert after.status_code == 201, (
        "after the 60s window the key's quota resets, got {0}: {1}".format(
            after.status_code, after.text[:200]
        )
    )
    assert app.count_links() == 3


def test_a_caller_whose_quota_is_spent_can_still_follow_links(app_factory):
    app = _keyed(app_factory, keys="alpha:1", LINKS_RATE_LIMIT_MAX="50")
    code = app.create("https://example.com/target", key="alpha").json()["code"]
