    for _ in range(3):
        response = app.visit(code, key="alpha")
        assert response.status_code == 307, (
            "redirects must never be refused because a creation quota is spent, "
            "got {0}".format(response.status_code)
        )
        assert response.headers["location"] == "https://example.com/target"


def test_stats_and_health_are_never_refused_because_a_key_quota_is_spent(app_factory):
