        stats = app.stats(code, key="alpha")
        health = app.health(key="alpha")
        assert stats.status_code == 200, stats.text[:200]
        assert health.status_code == 200, health.text[:200]


def test_with_limiting_disabled_keyed_and_unkeyed_callers_are_never_throttled(app_factory):
    app = app_factory(
        SHORTENER_API_KEYS=ALPHA_BETA,
        LINKS_RATE_LIMIT_ENABLED="false",
