    for i in range(15):
        keyed = app.create("https://example.com/k{0}".format(i), key="beta")
        plain = app.create("https://example.com/p{0}".format(i))
        assert keyed.status_code == 201, (i, keyed.text[:200])
        assert plain.status_code == 201, (i, plain.text[:200])

    assert app.count_links() == 30
"},{"path":"tests_pipeline/test_short_code_collision_retry.py","content":""""Collision handling: a repeated code is retried, never surfaced as a 500."""
import re

CODE_RE = re.compile("^[A-Za-z0-9]{4,32}$")


def test_a_generator_that_repeats_an_existing_code_still_yields_a_unique_code(app, force_codes):
    first = app.create("https://example.com/first")
    assert first.status_code == 201, first.text[:200]
    taken = first.json()["code"]

    stub = force_codes(app, [taken])
    second = app.create("https://example.com/second")

    assert stub.calls >= 2, (
        "the code generator was consulted {0} time(s): the service did not retry "
        "after the collision (or the generator could not be intercepted)".format(
            stub.calls
        )
    )
    assert second.status_code == 201, (
        "a collision must be retried, not returned as {0}: {1}".format(
            second.status_code, second.text[:200]
        )
    )
    code = second.json()["code"]
    assert code != taken, "the second link was handed the first link's code"
    assert CODE_RE.match(code), code


def test_two_consecutive_collisions_are_retried_rather_than_failing(app, force_codes):
    taken = app.create("https://example.com/first").json()["code"]

    stub = force_codes(app, [taken, taken])
    second = app.create("https://example.com/second")

    assert second.status_code == 201, (
        "two collisions must still resolve to a unique code, got {0}: {1}".format(
            second.status_code, second.text[:200]
        )
    )
    assert stub.calls >= 3, stub.calls
    assert second.json()["code"] != taken


def test_a_collision_leaves_exactly_two_distinct_rows_and_loses_neither_link(app, force_codes):
    taken = app.create("https://example.com/first").json()["code"]
    force_codes(app, [taken, taken])
    second = app.create("https://example.com/second").json()["code"]

    stored = [row["code"] for row in app.link_rows()]

    assert sorted(stored) == sorted([taken, second]), stored
    assert len(set(stored)) == 2, "the retry duplicated or clobbered a code"


def test_both_links_still_redirect_to_their_own_destination_after_a_collision(app, force_codes):
    taken = app.create("https://example.com/first").json()["code"]
    force_codes(app, [taken])
    second = app.create("https://example.com/second").json()["code"]

    assert app.visit(taken).headers["location"] == "https://example.com/first"
    assert app.visit(second).headers["location"] == "https://example.com/second"


def test_a_collision_never_produces_a_500(app, force_codes):
    taken = app.create("https://example.com/first").json()["code"]
    force_codes(app, [taken, taken, taken])

    response = app.create("https://example.com/second")

    assert response.status_code != 500, (
        "a code collision must not escape as a server error: " + response.text[:300]
    )
    assert response.status_code == 201, response.text[:200]
