import pytest


def test_an_unknown_code_returns_404_with_the_not_found_envelope(app, assert_error):
    response = app.visit("Ab3Cd9Z")

    assert response.status_code == 404, response.text[:200]
    error = assert_error(response)
    assert error["code"] == "not_found", error
    assert "location" not in set(k.lower() for k in response.headers.keys())


def test_an_unknown_code_creates_neither_a_link_nor_a_click(app):
    app.visit("Ab3Cd9Z")
    app.visit("Zz9Yy8X")

    assert app.link_rows() == [], "a missing code minted a row"
    assert app.click_rows() == [], "a missing code was counted as a click"


@pytest.mark.parametrize(
    "code",
    ["short", "waytoolongforacode", "abc-def", "abc_def", "1234567890"],
    ids=["too_short", "too_long", "hyphen", "underscore", "ten_digits"],
)
def test_a_malformed_code_is_a_plain_404_and_not_a_server_error(app, assert_error, code):
    response = app.visit(code)

    assert response.status_code == 404, (
        "{0!r} should be a plain 404, got {1}: {2}".format(
            code, response.status_code, response.text[:200]
        )
    )
    assert_error(response)
    assert app.click_rows() == []


def test_stats_for_an_unknown_code_is_404_and_creates_nothing(app, assert_error):
    response = app.stats("Ab3Cd9Z")

    assert response.status_code == 404, response.text[:200]
    assert assert_error(response)["code"] == "not_found"
    assert app.link_rows() == []


def test_a_404_does_not_disturb_an_existing_link(app):
    code = app.create("https://example.com/live").json()["code"]

    assert app.visit("Zz9Yy8X").status_code == 404

    assert app.visit(code).status_code == 307
    assert app.stats(code).json()["total_clicks"] == 1
