from datetime import datetime, timedelta, timezone


def test_one_successful_redirect_increments_the_click_count_by_exactly_one(app):
    code = app.create("https://example.com/a").json()["code"]
    assert app.stats(code).json()["total_clicks"] == 0

    assert app.visit(code).status_code == 307

    assert app.count_clicks() == 1, "exactly one click row per served redirect"
    assert app.stats(code).json()["total_clicks"] == 1


def test_three_redirects_produce_a_total_of_three_clicks(app):
    code = app.create("https://example.com/a").json()["code"]

    for _ in range(3):
        assert app.visit(code).status_code == 307

    assert app.count_clicks() == 3
    assert app.stats(code).json()["total_clicks"] == 3


def test_a_404_redirect_does_not_increment_any_click_count(app):
    code = app.create("https://example.com/a").json()["code"]
    assert app.visit(code).status_code == 307

    assert app.visit("Qq1Ww2E").status_code == 404

    assert app.count_clicks() == 1
    assert app.stats(code).json()["total_clicks"] == 1


def test_a_refused_expired_redirect_does_not_increment_the_click_count(app):
    code = app.create("https://example.com/a").json()["code"]
    assert app.visit(code).status_code == 307
    app.set_expiry(code, datetime.now(timezone.utc) - timedelta(minutes=5))

    for _ in range(3):
        assert app.visit(code).status_code == 410

    assert app.count_clicks() == 1, "a redirect that failed was still counted"
    assert app.stats(code).json()["total_clicks"] == 1


def test_clicks_are_attributed_to_their_own_link_only(app):
    first = app.create("https://example.com/a").json()["code"]
    second = app.create("https://example.com/b").json()["code"]

    app.visit(first)
    app.visit(first)
    app.visit(second)

    assert app.stats(first).json()["total_clicks"] == 2
    assert app.stats(second).json()["total_clicks"] == 1


def test_the_click_count_is_readable_immediately_after_the_redirect_returns(app):
    code = app.create("https://example.com/a").json()["code"]

    for expected in (1, 2, 3, 4):
        assert app.visit(code).status_code == 307
        assert app.stats(code).json()["total_clicks"] == expected, (
            "the count must be committed before the redirect is returned"
        )


def test_a_click_entry_records_the_referrer_and_user_agent_sent_with_the_redirect(app):
    code = app.create("https://example.com/a").json()["code"]

    app.visit(
        code,
        headers={"Referer": "https://news.test/story", "User-Agent": "pinning-agent/1.0"},
    )

    entries = app.stats(code).json()["clicks"]
    assert len(entries) == 1, entries
    assert entries[0]["referrer"] == "https://news.test/story", entries[0]
    assert entries[0]["user_agent"] == "pinning-agent/1.0", entries[0]
