"""Fixtures for the short-link HTTP behaviour suite.

Every test gets:

* its own SQLite file, handed to the service through ``LINKS_DB_PATH``;
* its own freshly imported application module, so startup-only configuration
  (notably ``SHORTENER_API_KEYS``) is re-read and the in-process rate limiter
  starts empty;
* a stub name resolver, so no test performs network I/O.

No test sleeps, no test shares state with another and no test depends on the
order in which the others ran.

Only environment variable names from the design's configuration list are set:
LINKS_DB_PATH, LINKS_BASE_URL, LINKS_RATE_LIMIT_ENABLED, LINKS_RATE_LIMIT_MAX,
LINKS_RATE_LIMIT_WINDOW_SECONDS, LINKS_TRUST_FORWARDED_FOR and
SHORTENER_API_KEYS.
"""
from __future__ import annotations

import importlib
import ipaddress
import secrets
import socket
import sqlite3
import string
import sys
import time as real_time
from contextlib import ExitStack
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional

import pytest
from fastapi.testclient import TestClient

ROOT = Path(__file__).resolve().parents[1]
for _candidate in (ROOT, ROOT / "src"):
    if _candidate.is_dir() and str(_candidate) not in sys.path:
        sys.path.insert(0, str(_candidate))

PUBLIC_IPV4 = "93.184.216.34"
PUBLIC_IPV6 = "2606:2800:220:1:248:1893:25c8:1946"
TS_FORMAT = "%Y-%m-%dT%H:%M:%S.%fZ"
BASE62 = string.ascii_letters + string.digits

BASE_ENV: Dict[str, Optional[str]] = {
    "LINKS_BASE_URL": "http://short.test",
    "LINKS_RATE_LIMIT_ENABLED": "false",
    "LINKS_RATE_LIMIT_MAX": "10",
    "LINKS_RATE_LIMIT_WINDOW_SECONDS": "60",
    "LINKS_TRUST_FORWARDED_FOR": "false",
    "SHORTENER_API_KEYS": "",
}

APP_MODULE_CANDIDATES = (
    "app.main",
    "app.app",
    "main",
    "app",
    "src.main",
    "src.app.main",
    "api.main",
    "server.main",
    "service.main",
    "shortener.main",
    "url_shortener.main",
    "links.main",
    "application",
    "server",
)

_APP_MODULE_NAME: Optional[str] = None


def _purge_root(root: str) -> None:
    for name in list(sys.modules):
        if name == root or name.startswith(root + "."):
            del sys.modules[name]


def _get_app_object(module: Any):
    obj = getattr(module, "app", None)
    if obj is not None and hasattr(obj, "router"):
        return obj
    factory = getattr(module, "create_app", None)
    if callable(factory):
        try:
            built = factory()
        except Exception:
            return None
        if built is not None and hasattr(built, "router"):
            return built
    return None


def _import_app_module():
    global _APP_MODULE_NAME
    errors: List[str] = []
    names = [_APP_MODULE_NAME] if _APP_MODULE_NAME else list(APP_MODULE_CANDIDATES)
    for name in names:
        _purge_root(name.split(".")[0])
        try:
            module = importlib.import_module(name)
        except Exception as exc:  # pragma: no cover - depends on layout
            errors.append("{0}: {1}: {2}".format(name, type(exc).__name__, exc))
            continue
        if _get_app_object(module) is None:
            errors.append("{0}: no ASGI `app` and no usable `create_app()`".format(name))
            continue
        _APP_MODULE_NAME = name
        return module
    raise RuntimeError(
        "Could not import the ASGI application. Tried:\n  " + "\n  ".join(errors)
    )


# ---------------------------------------------------------------------------
# stub resolver -- no test may touch real DNS
# ---------------------------------------------------------------------------
class FakeResolver:
    """Deterministic stand-in for :mod:`socket` name resolution."""

    def __init__(self) -> None:
        self.map: Dict[str, List[str]] = {}
        self.failures = set()
        self.lookups: List[str] = []

    def set(self, host: str, addresses) -> None:
        self.map[host.strip("[]").lower()] = list(addresses)

    def fail(self, host: str) -> None:
        self.failures.add(host.strip("[]").lower())

    def _addresses_for(self, host) -> List[str]:
        text = (host or "").strip("[]").lower()
        self.lookups.append(text)
        if text in self.failures:
            raise socket.gaierror(-2, "Name or service not known")
        if text in self.map:
            return list(self.map[text])
        try:
            ipaddress.ip_address(text)
            return [text]
        except ValueError:
            return [PUBLIC_IPV4]

    def getaddrinfo(self, host, port=0, family=0, type=0, proto=0, flags=0):
        try:
            portnum = int(port)
        except (TypeError, ValueError):
            portnum = 80
        out = []
        for addr in self._addresses_for(host):
            ip = ipaddress.ip_address(addr)
            if ip.version == 4:
                out.append((socket.AF_INET, socket.SOCK_STREAM, 6, "", (addr, portnum)))
            else:
                out.append(
                    (socket.AF_INET6, socket.SOCK_STREAM, 6, "", (addr, portnum, 0, 0))
                )
        return out

    def gethostbyname(self, host):
        for addr in self._addresses_for(host):
            if ipaddress.ip_address(addr).version == 4:
                return addr
        raise socket.gaierror(-2, "Name or service not known")

    def gethostbyname_ex(self, host):
        addrs = [
            a for a in self._addresses_for(host) if ipaddress.ip_address(a).version == 4
        ]
        return (host, [], addrs)


@pytest.fixture
def fake_dns(monkeypatch):
    resolver = FakeResolver()
    monkeypatch.setattr(socket, "getaddrinfo", resolver.getaddrinfo)
    monkeypatch.setattr(socket, "gethostbyname", resolver.gethostbyname)
    monkeypatch.setattr(socket, "gethostbyname_ex", resolver.gethostbyname_ex)
    return resolver


# ---------------------------------------------------------------------------
# the application under test
# ---------------------------------------------------------------------------
@dataclass
class Harness:
    client: TestClient
    asgi: Any
    module: Any
    db_path: str

    # ---- HTTP ----
    def create(
        self,
        url=None,
        key=None,
        xff=None,
        expires_at=None,
        headers=None,
        payload=None,
    ):
        if payload is None:
            body: Dict[str, Any] = {}
            if url is not None:
                body["url"] = url
            if expires_at is not None:
                body["expires_at"] = expires_at
        else:
            body = dict(payload)
        sent = dict(headers or {})
        if key is not None:
            sent["X-API-Key"] = key
        if xff is not None:
            sent["X-Forwarded-For"] = xff
        return self.client.post("/api/links", json=body, headers=sent)

    def visit(self, code, key=None, xff=None, headers=None):
        sent = dict(headers or {})
        if key is not None:
            sent["X-API-Key"] = key
        if xff is not None:
            sent["X-Forwarded-For"] = xff
        try:
            return self.client.get(
                "/" + str(code), headers=sent, follow_redirects=False
            )
        except TypeError:  # pragma: no cover - very old TestClient
            return self.client.get("/" + str(code), headers=sent, allow_redirects=False)

    def stats(self, code, key=None, **params):
        sent = {}
        if key is not None:
            sent["X-API-Key"] = key
        return self.client.get(
            "/api/links/{0}/stats".format(code),
            params=params or None,
            headers=sent,
        )

    def health(self, key=None):
        sent = {}
        if key is not None:
            sent["X-API-Key"] = key
        return self.client.get("/health", headers=sent)

    # ---- database ----
    def _rows(self, sql, params=()):
        con = sqlite3.connect(self.db_path)
        con.row_factory = sqlite3.Row
        try:
            return [dict(r) for r in con.execute(sql, params).fetchall()]
        except sqlite3.OperationalError as exc:
            raise AssertionError(
                "sqlite error {0!r} against {1}: does the service honour "
                "LINKS_DB_PATH and create its schema?".format(str(exc), self.db_path)
            )
        finally:
            con.close()

    def link_rows(self):
        return self._rows("SELECT * FROM links ORDER BY id")

    def click_rows(self):
        return self._rows("SELECT * FROM clicks ORDER BY id")

    def count_links(self):
        return len(self.link_rows())

    def count_clicks(self):
        return len(self.click_rows())

    def columns(self, table):
        return [r["name"] for r in self._rows("PRAGMA table_info({0})".format(table))]

    def table_names(self):
        rows = self._rows(
            "SELECT name FROM sqlite_master WHERE type = 'table' "
            "AND name NOT LIKE 'sqlite_%'"
        )
        return sorted(r["name"] for r in rows)

    def set_expiry(self, code, when: datetime) -> None:
        stamp = when.astimezone(timezone.utc).strftime(TS_FORMAT)
        con = sqlite3.connect(self.db_path)
        try:
            cur = con.execute(
                "UPDATE links SET expires_at = ? WHERE code = ?", (stamp, code)
            )
            con.commit()
            assert cur.rowcount == 1, "no links row with code {0!r}".format(code)
        finally:
            con.close()

    def db_dir_bytes(self) -> bytes:
        blob = b""
        base = Path(self.db_path)
        for path in sorted(base.parent.glob("*")):
            if path.is_file():
                blob += path.read_bytes()
        return blob


@pytest.fixture
def app_factory(tmp_path, monkeypatch, fake_dns):
    stack = ExitStack()
    counter = {"n": 0}

    def factory(**overrides) -> Harness:
        counter["n"] += 1
        db_path = tmp_path / "links-{0}.db".format(counter["n"])
        env: Dict[str, Optional[str]] = dict(BASE_ENV)
        env["LINKS_DB_PATH"] = str(db_path)
        for name, value in overrides.items():
            env[name] = value
        for name, value in env.items():
            if value is None:
                monkeypatch.delenv(name, raising=False)
            else:
                monkeypatch.setenv(name, str(value))
        module = _import_app_module()
        asgi = _get_app_object(module)
        assert asgi is not None, "application module exposes no ASGI app"
        try:
            client = TestClient(
                asgi,
                base_url="http://short.test",
                raise_server_exceptions=False,
                follow_redirects=False,
            )
        except TypeError:  # pragma: no cover
            client = TestClient(asgi, base_url="http://short.test")
        stack.enter_context(client)
        return Harness(client=client, asgi=asgi, module=module, db_path=str(db_path))

    try:
        yield factory
    finally:
        stack.close()


@pytest.fixture
def app(app_factory) -> Harness:
    return app_factory()


# ---------------------------------------------------------------------------
# fake clock -- windows are advanced, never slept through
# ---------------------------------------------------------------------------
class FakeClock:
    def __init__(self, start: float = 10000.0) -> None:
        self.now = float(start)
        self.installed: List[str] = []

    def __call__(self) -> float:
        return self.now

    def monotonic(self) -> float:
        return self.now

    def time(self) -> float:
        return self.now

    def perf_counter(self) -> float:
        return self.now

    def advance(self, seconds: float) -> None:
        self.now += float(seconds)


class _TimeShim:
    def __init__(self, clock: FakeClock, real) -> None:
        self._clock = clock
        self._real = real

    def monotonic(self) -> float:
        return self._clock.now

    def perf_counter(self) -> float:
        return self._clock.now

    def time(self) -> float:
        return self._clock.now

    def __getattr__(self, name):
        return getattr(self._real, name)


def _limiter_objects(harness: Harness):
    found = []
    state = getattr(harness.asgi, "state", None)
    for name in ("rate_limiter", "limiter", "rate_limit", "ratelimiter"):
        obj = getattr(state, name, None) if state is not None else None
        if obj is not None:
            found.append(obj)
    node = getattr(harness.asgi, "middleware_stack", None)
    depth = 0
    while node is not None and depth < 30:
        found.append(node)
        node = getattr(node, "app", None)
        depth += 1
    return found


@pytest.fixture
def fake_clock(monkeypatch):
    """Install a substitutable clock into the limiter and return it."""

    def _install(harness: Harness, start: float = 10000.0) -> FakeClock:
        clock = FakeClock(start)
        harness.client.get("/health")  # force the middleware stack to be built
        for obj in _limiter_objects(harness):
            if hasattr(obj, "clock"):
                try:
                    monkeypatch.setattr(obj, "clock", clock, raising=False)
                except Exception:  # pragma: no cover - exotic objects
                    continue
                clock.installed.append("{0}.clock".format(type(obj).__name__))
        root = harness.module.__name__.split(".")[0]
        for name, mod in list(sys.modules.items()):
            if mod is None:
                continue
            if name != root and not name.startswith(root + "."):
                continue
            if getattr(mod, "time", None) is real_time:
                monkeypatch.setattr(mod, "time", _TimeShim(clock, real_time))
                clock.installed.append(name + ".time")
        return clock

    return _install


# ---------------------------------------------------------------------------
# forcing short code collisions
# ---------------------------------------------------------------------------
def _random_code(length: int = 7) -> str:
    return "".join(secrets.choice(BASE62) for _ in range(length))


class CodeStub:
    """Stands in for the service's short code generator."""

    def __init__(self, queue, length: int = 7) -> None:
        self.queue = list(queue)
        self.length = length
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        if self.queue:
            return self.queue.pop(0)
        return _random_code(self.length)


class CharStub:
    """Fallback: feed the wanted codes one character at a time."""

    def __init__(self, queue, length: int, original) -> None:
        self.chars: List[str] = []
        for code in queue:
            self.chars.extend(list(code))
        self.length = max(int(length), 1)
        self.consumed = 0
        self._original = original

    def __call__(self, sequence):
        if self.chars:
            self.consumed += 1
            return self.chars.pop(0)
        return self._original(sequence)

    @property
    def calls(self) -> int:
        return self.consumed // self.length


_HINTS = ("gen", "make", "new", "random", "build", "mint", "alloc")
_BAD = ("max", "attempt", "length", "len", "pattern", "alphabet", "chars", "error")


def _find_code_generators(module):
    root = module.__name__.split(".")[0]
    found = []
    for name, mod in list(sys.modules.items()):
        if mod is None:
            continue
        if name != root and not name.startswith(root + "."):
            continue
        for attr in dir(mod):
            low = attr.lower()
            if "code" not in low:
                continue
            if any(bad in low for bad in _BAD):
                continue
            if not any(hint in low for hint in _HINTS):
                continue
            value = getattr(mod, attr, None)
            if not callable(value):
                continue
            owner = getattr(value, "__module__", "") or ""
            if owner != root and not owner.startswith(root + "."):
                continue
            found.append((mod, attr))
    return found


@pytest.fixture
def force_codes(monkeypatch):
    """Make the next short codes the service mints be exactly ``queue``.

    Once the queue is exhausted the stub returns fresh random codes, so a
    service that retries forever terminates instead of hanging the suite.
    """

    def _force(harness: Harness, queue):
        import os

        length = int(os.environ.get("LINKS_CODE_LENGTH", "7"))
        targets = _find_code_generators(harness.module)
        if targets:
            stub = CodeStub(queue, length)
            for mod, attr in targets:
                monkeypatch.setattr(mod, attr, stub)
            return stub
        stub = CharStub(queue, length, secrets.choice)
        monkeypatch.setattr(secrets, "choice", stub)
        return stub

    return _force


# ---------------------------------------------------------------------------
# small assertion helpers, delivered as fixtures so no cross-module import is
# needed between test files
# ---------------------------------------------------------------------------
@pytest.fixture
def assert_error():
    def _assert(response) -> Dict[str, Any]:
        ctype = response.headers.get("content-type", "")
        assert "application/json" in ctype, (
            "error responses must be JSON, got {0!r}: {1}".format(
                ctype, response.text[:200]
            )
        )
        body = response.json()
        assert isinstance(body, dict) and "error" in body, (
            "error body must be an object with an 'error' member, got "
            + repr(body)[:300]
        )
        err = body["error"]
        assert isinstance(err, dict), "error must be an object, got " + repr(err)[:300]
        assert isinstance(err.get("code"), str) and err["code"], (
            "error.code must be a non-empty string, got " + repr(err)[:300]
        )
        assert isinstance(err.get("message"), str) and err["message"], (
            "error.message must be a non-empty string, got " + repr(err)[:300]
        )
        return err

    return _assert


@pytest.fixture
def parse_ts():
    def _parse(value: str) -> datetime:
        assert isinstance(value, str), "timestamp must be a string, got " + repr(value)
        text = value.strip()
        if text.endswith("Z") or text.endswith("z"):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    return _parse

"""Open redirect surface: only http(s) may ever become a Location header."""
import pytest

DANGEROUS = [
    "javascript:alert(1)",
    "JavaScript:alert(document.domain)",
    "data:text/html,<script>alert(1)</script>",
    "file:///etc/passwd",
]


@pytest.mark.parametrize("target", DANGEROUS)
def test_a_dangerous_scheme_is_refused_at_creation_with_4xx(app, assert_error, target):
    response = app.create(target)

    assert 400 <= response.status_code < 500, (
        "{0!r} must be refused at creation, got {1}: {2}".format(
            target, response.status_code, response.text[:200]
        )
    )
    assert_error(response)


@pytest.mark.parametrize("target", DANGEROUS)
def test_a_dangerous_scheme_leaves_no_row_in_the_links_table(app, target):
    app.create(target)

    rows = app.link_rows()
    assert rows == [], (
        "a rejected destination was still written to the database: " + repr(rows)
    )


def test_a_rejected_scheme_uses_the_unsupported_scheme_error_code(app, assert_error):
    response = app.create("javascript:alert(1)")

    assert response.status_code == 400, response.text[:200]
    assert assert_error(response)["code"] == "unsupported_scheme"


def test_no_code_exists_to_reach_a_rejected_destination(app):
    for target in DANGEROUS:
        app.create(target)

    assert app.link_rows() == []
    assert app.visit("aB3dEf9").status_code == 404


def test_a_url_carrying_a_newline_cannot_be_stored_for_a_location_header(app, assert_error):
    response = app.create("https://example.com/ok\r\nX-Injected: 1")

    assert 400 <= response.status_code < 500, response.text[:200]
    assert_error(response)
    assert app.link_rows() == []


def test_http_and_https_destinations_are_still_accepted(app):
    for target in ("http://example.com/plain", "https://example.com/secure"):
        response = app.create(target)
        assert response.status_code == 201, (target, response.text[:200])

    assert app.count_links() == 2
